import{_ as t,o as n,c as o,ah as r}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Enrolment and agreement","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/apprenant/inscription.md","filePath":"src/en/guide/apprenant/inscription.md"}'),a={name:"en/guide/apprenant/inscription.md"};function i(s,e,h,g,l,d){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="enrolment-and-agreement" tabindex="-1">Enrolment and agreement <a class="header-anchor" href="#enrolment-and-agreement" aria-label="Permalink to &quot;Enrolment and agreement&quot;">​</a></h1><p>When the decision is &quot;admitted&quot;, Kura creates your <strong>enrolment</strong>. It stays &quot;pending signature&quot; until you have signed your training agreement. Everything happens in <strong>Journeys → My enrolment</strong>.</p><h2 id="complete-your-file" tabindex="-1">Complete your file <a class="header-anchor" href="#complete-your-file" aria-label="Permalink to &quot;Complete your file&quot;">​</a></h2><p>Before you can sign, three things must be in place. The <strong>My enrolment</strong> page lists what is missing.</p><h3 id="a-cohort" tabindex="-1">A cohort <a class="header-anchor" href="#a-cohort" aria-label="Permalink to &quot;A cohort&quot;">​</a></h3><p>Your <strong>cohort</strong> is the session you will follow, with its start and end dates. It is chosen by the advisor at admission, or otherwise by the Pedagogical Coordinator, who tells you by e-mail. You do not choose it yourself.</p><h3 id="a-format" tabindex="-1">A format <a class="header-anchor" href="#a-format" aria-label="Permalink to &quot;A format&quot;">​</a></h3><p>You confirm or change your <strong>format</strong> (online, hybrid, in person) among those the cohort offers, with their price. You can change it <strong>until the agreement is signed</strong>; it is then fixed.</p><h3 id="two-consents" tabindex="-1">Two consents <a class="header-anchor" href="#two-consents" aria-label="Permalink to &quot;Two consents&quot;">​</a></h3><p>Answer each <strong>separately</strong> (&quot;I agree&quot; or &quot;I do not agree&quot;):</p><ul><li><strong>Teaching reuse of the tutored project</strong>: NextBoxx may reuse, for teaching purposes, the project you carry out during the training;</li><li><strong>Image rights</strong>: NextBoxx may show you in its recordings.</li></ul><p>Both answers are required to sign, but nothing obliges you to agree. You can change your mind <strong>at any time</strong>; each change is recorded. A refusal is respected everywhere: the team sees in the cohort page which learners have not given their image rights and shares no recording in which you appear.</p><h2 id="sign-the-agreement" tabindex="-1">Sign the agreement <a class="header-anchor" href="#sign-the-agreement" aria-label="Permalink to &quot;Sign the agreement&quot;">​</a></h2><p>When the file is complete, Kura sends you a message and the <strong>My enrolment</strong> page shows &quot;Your agreement is ready&quot;.</p><ol><li>Click <strong>Read the agreement</strong>. It includes the general terms, then the specific terms: the parties, the training, the cohort, the format, the <strong>price excluding tax</strong> and the <strong>schedule</strong> of the three payments with their dates.</li><li>Scroll to the end: the box &quot;I have read the agreement to the end and accept its terms&quot; only becomes active then.</li><li>Click <strong>Get a code</strong>. A <strong>6-digit</strong> code is sent to your e-mail address. It is valid for <strong>15 minutes</strong>, works only once, and you have 5 tries.</li><li>Enter the code and click <strong>Sign the agreement</strong>.</li></ol><p>Your agreement is then &quot;awaiting counter-signature&quot;: the pedagogical team counter-signs for edPage group (automatically or by hand, depending on the chosen setting). You then receive the sealed PDF by e-mail; it is also in <strong>My documents</strong>, under the reference <code>CONV-NB-YYYY-XXX</code>.</p><p>On counter-signature, your enrolment becomes <strong>active</strong>, and the <strong>format, cohort and price are fixed</strong>. The first invoice is issued (see <a href="./paiements.html">Payments</a>).</p><h2 id="if-you-are-a-minor" tabindex="-1">If you are a minor <a class="header-anchor" href="#if-you-are-a-minor" aria-label="Permalink to &quot;If you are a minor&quot;">​</a></h2><p>For a minor learner, the <strong>legal guardian</strong> gives consent and signs, without needing a Kura account:</p><ol><li>In <strong>My enrolment</strong>, under &quot;Legal guardian&quot;, enter their full name and e-mail address, then <strong>Send the link</strong>.</li><li>They receive a link to give the two consents. The link is valid for <strong>7 days</strong> and works only once; <strong>Send a new link</strong> replaces the previous one.</li><li>When the file is complete, you send them the agreement with <strong>Send the agreement to my guardian</strong>. They read it, receive a 6-digit code at their own address and sign from a second link, valid 7 days.</li></ol><p>Only the legal guardian&#39;s consents and signature count.</p><h2 id="when-a-company-funds-you" tabindex="-1">When a company funds you <a class="header-anchor" href="#when-a-company-funds-you" aria-label="Permalink to &quot;When a company funds you&quot;">​</a></h2><p>If a company funds part of your training, the Coordinator records it <strong>before the signature</strong>. The agreement states the split (for example 60% learner, 40% funder) and each instalment is invoiced to each for their share.</p><p>A <strong>tripartite agreement</strong> is also prepared when your agreement is counter-signed. It repeats the same terms; the funder signs it, from their &quot;Funded learners&quot; space. It blocks neither your enrolment nor billing. You receive its PDF once both parties have signed.</p><h2 id="if-your-cohort-changes" tabindex="-1">If your cohort changes <a class="header-anchor" href="#if-your-cohort-changes" aria-label="Permalink to &quot;If your cohort changes&quot;">​</a></h2><p>Any change of cohort after signing (postponement decided by NextBoxx, force majeure) <strong>replaces the agreement</strong>:</p><ul><li>the old one is kept, marked &quot;replaced&quot;;</li><li>your enrolment goes back to pending signature;</li><li>a new agreement, <strong>at the same price and in the same format</strong>, is offered to you. You are told by e-mail.</li></ul><p>What you have already paid is kept and deducted from the instalments of the new agreement.</p>',28)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
